"use client";

/**
 * The package-copies source's live half: no request at all. The report is generated by
 * `scripts/report-package-copies.mjs` and shipped with the app, so the dock reads it
 * synchronously and never shows a loading state for it.
 */

import report from "./package-copies.report.json";
import { muteItem, unmuteItem } from "../item-mute";
import type { AttentionSourceState } from "../types";
import {
  PACKAGE_COPIES_SOURCE_ID,
  PACKAGE_COPIES_SOURCE_LABEL,
  packageCopiesItems,
  summarizePackageCopies,
  type PackageCopiesReport,
} from "./package-copies";

export function usePackageCopiesSource(enabled: boolean): AttentionSourceState {
  const items = enabled
    ? packageCopiesItems(report as unknown as PackageCopiesReport, {
        muteLocally: (key, ms) => muteItem(key, ms),
        unmuteLocally: (key) => unmuteItem(key),
      })
    : [];
  return {
    id: PACKAGE_COPIES_SOURCE_ID,
    label: PACKAGE_COPIES_SOURCE_LABEL,
    items,
    status: enabled ? "ok" : "idle",
    error: null,
    loud: false,
    summarize: summarizePackageCopies,
    review: null,
    refetch: () => {},
  };
}
